import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group, flags_in_window, longest_flag_streak, monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_dedupe_keeps_last_record_and_sorts_survivors():
    events = parse_transcript_log(["x,9,1", "y,2,1", "a,4,0", "x,2,0"])
    assert dedupe_transcripts(events) == [events[3], events[1], events[2]]


def test_pooled_and_summary_count_transcripts_not_groups():
    groups = {"empty": [], "a": parse_transcript_log(["x,1,1"]),
              "b": parse_transcript_log(["y,3,1", "z,5,0"])}
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_window_boundaries():
    assert flags_in_window([4, 2, 1], 0) == 0
    assert flags_in_window([4, 2, 1], 2) == 3
    assert flags_in_window([4, 2, 1], 10) == 7


def test_parser_skips_comments_and_blanks_and_strips_fields():
    assert parse_transcript_log(["", "  ", "  # header", " x , 3 , 0 ", "y,2, "]) == [
        {"id": "x", "day": 3, "flagged": False},
        {"id": "y", "day": 2, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["x,2", "x,2,1,0", "x,abc,1"])
def test_parser_reports_input_line_number(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["  # comment", "x,1,1", "", line])


def test_daily_counts_fill_gaps_and_ignore_out_of_range_events():
    events = parse_transcript_log(["a,0,1", "b,2,1", "c,2,1", "d,4,0", "e,5,1"])
    assert daily_flag_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_flag_counts(events, 4, 1) == []


def test_group_rates_and_ranking():
    groups = {"z": [{"flagged": True}], "empty": [], "b": [{"flagged": False}],
              "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0),
    ]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]


def test_longest_streak_resets_after_nonpositive_counts():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4]) == 2
    assert longest_flag_streak([]) == 0
